/* Static geography for the globe, generated by tools/gen_geodata.py. */
#ifndef GEODATA_H
#define GEODATA_H

/* Land mask: GEO_COLS x GEO_ROWS cells of GEO_GRID_DEG degrees, row 0 at the
 * north pole, column 0 at 180 W. Bit k = row * GEO_COLS + col, LSB first. */
#define GEO_GRID_DEG 3
#define GEO_COLS     (360 / GEO_GRID_DEG)
#define GEO_ROWS     (180 / GEO_GRID_DEG)

extern const unsigned char GEO_LAND[(GEO_COLS * GEO_ROWS + 7) / 8];

/* Label point of each country, sorted by code: where stations without
 * coordinates of their own are placed. */
typedef struct {
	char  code[3];           /* ISO 3166-1 alpha-2, upper case */
	float lat, lon;
} geo_country;

extern const geo_country GEO_COUNTRIES[];
extern const int GEO_COUNTRY_COUNT;

#endif
